SELECT analytics_order_facts.region, SUM(analytics_order_facts.net_revenue) AS net_revenue FROM analytics_order_facts WHERE analytics_order_facts.year = 2022 AND analytics_order_facts.month = 7 AND analytics_order_facts.channel = 'wholesale' AND analytics_order_facts.customer_segment = 'enterprise' AND analytics_order_facts.category = 'category_07' AND analytics_order_facts.payment_method = 'card' GROUP BY analytics_order_facts.region ORDER BY net_revenue DESC, analytics_order_facts.region ASC LIMIT 12
